export default {"id":"launchkey-level-8","number":8,"title":"Real Time Scale Engine & Quantization","skillBand":"Textbook","duration":"From the course textbook","summary":"The real-time Scale Engine built into the Launchkey MK4 61 quantizes incoming keybed performance data to a user-selected musical key and scale. This module details scale engine activation, parameter configuration via encoders, long-press no","modules":[{"id":"launchkey-m-8-1-1","code":"8.1","title":"Real-Time Scale Engine & Quantization","blurb":"The real-time Scale Engine built into the Launchkey MK4 61 quantizes incoming keybed performance data to a user-selected musical key and scale. This module details scale engine activation, parameter configuration via encoders, long-press no","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-23","title":"Section overview","blocks":[{"type":"step","title":"Section 8.1 — Scale Quantizer Activation & Operational Modes","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The real-time Scale Engine built into the Launchkey MK4 61 quantizes incoming keybed performance data to a user-selected musical key and scale. This module details scale engine activation, parameter configuration via encoders, long-press non-destructive inspection, and the mathematical differences among the three correction behaviors: <strong>Snap to Scale</strong>, <strong>Filter out of Scale</strong>, and <strong>Easy Scale</strong>."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Engage and disengage the internal Scale Engine via the dedicated <code>Scale</code> button.","Configure the Root Note (Encoder 1), Scale Type (Encoder 2), and Correction Mode (Encoder 3).","Execute non-destructive Scale inspection via the <strong>Long-Press</strong> protocol.","Formulate the pitch-quantization algorithm for <strong>Snap to Scale</strong>.","Formulate the MIDI suppression algorithm for <strong>Filter out of Scale</strong>.","Formulate the white-key linear remapping algorithm for <strong>Easy Scale</strong> and detail the octave-alignment caveat for non-heptatonic scales."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-8-1-1","title":"8.1.1: Scale Engine Activation & Encoder Page","blocks":[{"type":"step","title":"8.1.1: Scale Engine Activation & Encoder Page","blocks":[{"type":"prose","html":"The Launchkey MK4 61 provides a dedicated, backlit <code>Scale</code> button located above the display."},{"type":"list","items":["<strong>Primary Toggle</strong>: Pressing <code>Scale</code> toggles the scale quantizer on (illuminated bright blue) and off (unlit).","<strong>Automatic Encoder Page</strong>: When Scale is enabled, Encoders 1–3 automatically take command of the scale engine parameters:"],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    SCALE ENGINE ENCODER PARAMETER MATRIX                      |\n+---------------+-------------------+---------------------+---------------------+\n| Encoder       | Parameter Name    | Default Value       | Permitted Values    |\n+---------------+-------------------+---------------------+---------------------+\n| **Encoder 1** | **Root Note**     | **C**               | C, C#, D ... A#, B  |\n| **Encoder 2** | **Scale Type**    | **Major**           | 30 Documented Scales|\n| **Encoder 3** | **Behaviour**     | **Snap to Scale**   | Snap, Filter, Easy  |\n+---------------+-------------------+---------------------+---------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-8-1-2","title":"8.1.2: Non-Destructive Long-Press Inspection","blocks":[{"type":"step","title":"8.1.2: Non-Destructive Long-Press Inspection","blocks":[{"type":"prose","html":"To view or adjust the active Scale parameters without accidentally toggling the scale engine off:"},{"type":"list","items":["<strong>Long-Press <code>Scale</code></strong>: Press and hold <code>Scale</code> for 1 second.","The OLED screen and Encoders 1–3 open the Scale configuration view, but the enabled/disabled state of the engine remains completely unchanged."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-8-1-3","title":"8.1.3: Behavior 1 — Snap to Scale (Default)","blocks":[{"type":"step","title":"8.1.3: Behavior 1 — Snap to Scale (Default)","blocks":[{"type":"prose","html":"In <strong>Snap to Scale</strong> mode:"},{"type":"list","items":["<strong>Mathematical Quantization</strong>: When a physical key outside the selected scale is struck, the internal processor automatically quantizes (rounds) the note to the nearest valid in-scale pitch.","<strong>Deterministic Rounding</strong>: If an out-of-scale note is equidistant between two scale degrees, the engine rounds down to the lower adjacent scale tone.","<strong>Application</strong>: Ideal for live expressive performance, ensuring zero wrong notes while retaining natural finger movement across the entire keybed."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-8-1-4","title":"8.1.4: Behavior 2 — Filter out of Scale","blocks":[{"type":"step","title":"8.1.4: Behavior 2 — Filter out of Scale","blocks":[{"type":"prose","html":"In <strong>Filter out of Scale</strong> mode:"},{"type":"list","items":["<strong>MIDI Suppression</strong>: Striking an in-scale key transmits normal MIDI Note On/Off events. Striking an out-of-scale key <strong>transmits zero MIDI data</strong>.","<strong>Acoustic Result</strong>: Out-of-scale keys are completely muted/silent.","<strong>Application</strong>: Educational ear training and strict diatonic composition."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-8-1-5","title":"8.1.5: Behavior 3 — Easy Scale","blocks":[{"type":"step","title":"8.1.5: Behavior 3 — Easy Scale","blocks":[{"type":"prose","html":"In <strong>Easy Scale</strong> mode:"},{"type":"list","items":["<strong>Linear White-Key Remapping</strong>: All notes belonging to the selected scale are mapped sequentially onto the <strong>physical white keys</strong> of the keybed.","<strong>Black Key Deactivation</strong>: The physical black keys are deactivated (filtered).","<strong>The Heptatonic Octave Rule &amp; Non-7-Note Caveat</strong>:","<em>7-Note (Heptatonic) Scales</em> (e.g., Major, Natural Minor, Dorian): Each physical octave of white keys (C to B, 7 keys) corresponds exactly to one musical octave of the scale. Physical C always triggers the scale root.","<em>Non-7-Note Scales</em> (e.g., 5-note Pentatonics, 6-note Blues/Whole Tone, 8-tone Diminished): Because the scale contains fewer or more than 7 notes, successive octaves shift across the white keys and <strong>do not line up with physical keyboard octaves</strong>."],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">EASY SCALE OCTAVE MAPPING (C MAJOR PENTATONIC - 5 NOTES: C, D, E, G, A):\nPhysical White Key:   [ C ]   [ D ]   [ E ]   [ F ]   [ G ]   [ A ]   [ B ]   [ C(next) ]\nMapped Scale Pitch:     C       D       E       G       A       C       D         E\n                      (Root)                  (Note 4)(Note 5)(Root!)\n*Notice: Physical A plays Root C; Physical C(next) plays Note 3 (E).*</pre>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Scale button toggle; Encoders 1–3 (Root, Scale, Behaviour); non-destructive long-press; Snap to Scale rounding; Filter out of Scale silence; Easy Scale white-key mapping; octave misalignment caveat for non-7-note scales.","<strong>mustNotCover</strong>: Invention of undocumented fourth correction behaviors."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Enable Scale Mode. Set Root to <code>C</code>, Scale to <code>Major</code>, and test the black keys under <strong>Snap to Scale</strong> (they round to white-key pitches), under <strong>Filter</strong> (they are completely silent), and under <strong>Easy Scale</strong> (white keys play sequential scale degrees)."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Filter mode generates zero MIDI packets when physical C♯ is struck in C Major.","Long-pressing <code>Scale</code> brings up the parameter display without disabling the engine."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-8-2-2","code":"8.2","title":"Real-Time Scale Engine & Quantization","blurb":"The Novation Launchkey MK4 61 contains exactly 30 officially documented musical scale algorithms in firmware. These scales govern real-time keybed quantization, Arpeggiator harmonic constraints, and the generative Chord Sets utilized by the","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-24","title":"Section overview","blocks":[{"type":"step","title":"Section 8.2 — Complete Catalog of the 30 Documented Scales","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The Novation Launchkey MK4 61 contains exactly <strong>30 officially documented musical scale algorithms</strong> in firmware. These scales govern real-time keybed quantization, Arpeggiator harmonic constraints, and the generative Chord Sets utilized by the Chord Map engine. This module provides the authoritative, cited catalog of all 30 scales, their interval structures, and their associative chord set groupings."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Itemize the authoritative catalog of all 30 official scale types.","Differentiate standard Western diatonic modes from synthetic, symmetric, and world scale modes.","Formulate how scale selection dictates the harmonic library loaded by the Chord Map engine.","Apply the firmware versioning rule regarding scale names."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-8-2-1","title":"8.2.1: Complete Catalog of the 30 Official Scales","blocks":[{"type":"step","title":"8.2.1: Complete Catalog of the 30 Official Scales","blocks":[{"type":"prose","html":"The Launchkey MK4 61 firmware implements the following 30 scales, selectable via Encoder 2:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                 THE 30 OFFICIAL LAUNCHKEY MK4 SCALE TYPES                     |\n+-----+---------------------------+---------------------------------------------+\n| #   | Scale Name (OLED Readout) | Musical Interval Structure (Semitone Steps) |\n+-----+---------------------------+---------------------------------------------+\n| 1   | **Major**                 | 1, 2, 3, 4, 5, 6, 7 (W-W-H-W-W-W-H)         |\n| 2   | **Minor** (Natural Minor) | 1, 2, b3, 4, 5, b6, b7 (W-H-W-W-H-W-W)      |\n| 3   | **Dorian**                | 1, 2, b3, 4, 5, 6, b7                       |\n| 4   | **Mixolydian**            | 1, 2, 3, 4, 5, 6, b7                        |\n| 5   | **Lydian**                | 1, 2, 3, #4, 5, 6, 7                        |\n| 6   | **Phrygian**              | 1, b2, b3, 4, 5, b6, b7                     |\n| 7   | **Locrian**               | 1, b2, b3, 4, b5, b6, b7                    |\n| 8   | **Whole Tone**            | 1, 2, 3, #4, #5, b7 (W-W-W-W-W-W)           |\n| 9   | **Half Whole Dim**        | 1, b2, b3, 3, b5, 5, 6, b7 (H-W-H-W...)     |\n| 10  | **Whole Half Diminished** | 1, 2, b3, 4, b5, #5, 6, 7 (W-H-W-H...)      |\n| 11  | **Blues**                 | 1, b3, 4, b5, 5, b7                         |\n| 12  | **Minor Pentatonic**      | 1, b3, 4, 5, b7                             |\n| 13  | **Major Pentatonic**      | 1, 2, 3, 5, 6                               |\n| 14  | **Harmonic Minor**        | 1, 2, b3, 4, 5, b6, 7                       |\n| 15  | **Harmonic Major**        | 1, 2, 3, 4, 5, b6, 7                        |\n| 16  | **Dorian #4**             | 1, 2, b3, #4, 5, 6, b7                      |\n| 17  | **Melodic Minor**         | 1, 2, b3, 4, 5, 6, 7 (Jazz Minor)           |\n| 18  | **Hirajoshi**             | 1, 2, b3, 5, b6 (Japanese pentatonic)       |\n| 19  | **Kumoi**                 | 1, 2, b3, 5, 6 (Japanese pentatonic)        |\n| 20  | **Hungarian Minor**       | 1, 2, b3, #4, 5, b6, 7 (Double Harmonic Min)|\n| 21  | **Lydian Augmented**      | 1, 2, 3, #4, #5, 6, 7                       |\n| 22  | **Lydian Dominant**       | 1, 2, 3, #4, 5, 6, b7 (Overtone scale)      |\n| 23  | **In Sen** (In-Sen)       | 1, b2, 4, 5, b7 (Traditional Japanese)      |\n| 24  | **Iwato**                 | 1, b2, 4, b5, b7 (Traditional Japanese)     |\n| 25  | **Pelog-Selisir**         | 1, b2, b3, 5, b6 (Balinese Gamelan)         |\n| 26  | **Super Locrian**         | 1, b2, b3, b4, b5, b6, b7 (Altered scale)   |\n| 27  | **Bhairav**               | 1, b2, 3, 4, 5, b6, 7 (Hindustani Thaat)    |\n| 28  | **Pelog-Tembung**         | 1, 2, 4, 5, b6 (Gamelan variant)            |\n| 29  | **8-tone Spanish**         | 1, b2, b3, 3, 4, b5, b6, b7                 |\n| 30  | **Phrygian Dominant**      | 1, b2, 3, 4, 5, b6, b7 (Spanish Gypsy / Ahava)|\n+-----+---------------------------+---------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-8-2-2","title":"8.2.2: Associative Chord Set Grouping","blocks":[{"type":"step","title":"8.2.2: Associative Chord Set Grouping","blocks":[{"type":"prose","html":"When Scale Mode is engaged, the selected scale dynamically determines which <strong>Chord Set</strong> is loaded into the <strong>Chord Map</strong> engine (Module 9). Closely related modes (e.g., Major Pentatonic and Major, or Dorian and Minor) share common harmonic foundations, automatically generating musically cohesive progressions across the 40 Chord Map banks."}]}],"minutes":8},{"id":"launchkey-l-8-2-3","title":"8.2.3: Firmware Discrepancy Tracking Rule","blocks":[{"type":"step","title":"8.2.3: Firmware Discrepancy Tracking Rule","blocks":[{"type":"list","items":["The 30 scale names tabulated above represent the complete, locked authority documented by Novation.","If future firmware releases append new scale variants, they must be recorded as explicit version notes. No speculative or invented scale names may be added to the core curriculum."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Exact citation of all 30 documented scale names; mathematical interval definitions; Chord Set associative relationship; strict grounding rule.","<strong>mustNotCover</strong>: Invention of unlisted microtonal tunings or undocumented 31st+ scale names."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Rotate Encoder 2 through all 30 scale types in Scale mode. Select <code>Phrygian Dominant</code>, verify the interval structure on the OLED display, and play a Spanish/Flamenco phrase using white and black keys under <code>Snap to Scale</code>."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["All 30 scale names appear in the exact order tabulated.","Scale quantizer locks performance strictly to the Phrygian Dominant mode (<code>1, b2, 3, 4, 5, b6, b7</code>)."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
